WITH incoming AS (SELECT * FROM jsonb_populate_record(NULL::public.explore_content, '{"content_id": "87aca241-c8d5-4c45-b7d6-b786b08f7d01", "content_type": "QUICK_LEARN", "title": "Gluten in unexpected places", "subtitle": "A shared-kitchen check, from sponges to spreads.", "domain": "KNOW", "topic": "Cross-contact", "interaction_type": "KNOWLEDGE", "difficulty": null, "estimated_minutes": 3, "intro": "Gluten-free ingredients are only part of the picture. Cross-contact happens when gluten transfers from another food or object.", "content_body": {"format": "quick_learn_v1", "cards": [{"title": "A sponge can carry crumbs", "body": "A sponge or dishcloth used on gluten-containing food can transfer residue to dishes. Use a separate clean sponge or cloth for gluten-free cookware. Wash dishes thoroughly with warm, soapy water and rinse; a quick rinse alone is not enough."}, {"title": "Check the shared spreads", "body": "A knife used on regular bread can leave crumbs in butter or jam. Use a separate gluten-free spread and clean utensils."}, {"title": "Look beyond the ingredients", "body": "Shared bread toasters, pasta water, and oil used for breaded food can transfer gluten. Use separate equipment where needed, fresh pasta water, and a fryer that is not shared with gluten-containing food. Heat does not remove gluten."}], "kitchen_check": {"question": "You’re making a gluten-free snack. Someone offers to wash your plate with the sponge just used to wipe up bread crumbs. What could you do?", "options": [{"text": "Use the same sponge after a quick rinse", "feedback": "A quick rinse may leave gluten-containing residue. Choose a separate clean sponge or cloth and wash the plate thoroughly."}, {"text": "Ask for a separate clean sponge or cloth", "feedback": "Yes—then wash the plate with warm, soapy water and rinse. Check your utensils and preparation area too."}, {"text": "Skip washing because the plate looks clean", "feedback": "Appearance alone doesn’t tell you whether gluten 